R.append((7497836,
("Satay de verduras", "Un arcoíris de verduras asadas con una salsa picante de cacahuate y una ensalada aromática.", "2", "718 g",
 ["2 cucharaditas de aceite de colza", "1 pimiento rojo, cortado en 6 gajos", "1 pimiento verde, cortado en 6 gajos", "1 calabacín, en trozos", "1 berenjena, en trozos", "2 cebollas moradas, cortadas en 6 gajos", "1 cucharadita de comino molido", "una buena pizca de pimienta negra", "1 cebolla pequeña, picada", "2 dientes de ajo, machacados", "1 chile, finamente picado", "1 cucharadita colmada de maicena disuelta en 1 cucharada de agua", "1 cucharada de mantequilla de cacahuate", "1 cucharadita de salsa de soya sin gluten reducida en sal", "1 cucharadita de edulcorante granulado", "10 cm de pepino, rallado en tiras finas como palitos de fósforo", "3 cebollines, cortados en tiras finas como palitos de fósforo", "1 cucharada de cilantro picado", "medio limón verde"],
 ["Precaliente el horno a 180 °C (marca de gas 4). Ponga el aceite en una bandeja para hornear, agregue las verduras, espolvoree con el comino y la pimienta, y mezcle bien para que todas las verduras queden cubiertas.", "Hornee de 30 a 40 minutos, moviendo las verduras un par de veces durante la cocción para que se cocinen de manera uniforme.", "Mientras tanto, para hacer la salsa satay, ponga la cebolla en una cacerola con el ajo, el chile y 150 ml de agua y deje que hierva. Cocine a fuego lento 5 minutos hasta que la cebolla esté suave. Incorpore poco a poco la maicena y siga revolviendo hasta que espese. Agregue la mantequilla de cacahuate, la salsa de soya y el edulcorante, y licúe hasta que quede suave.", "Para la ensalada, mezcle el pepino y el cebollín, espolvoree con el cilantro y sirva con un chorrito de limón verde."],
 ["El análisis nutricional anterior incluye una sugerencia de ensalada para acompañar.", "Puede cortar las verduras en trozos más pequeños, ensartarlas en brochetas y asarlas a la parrilla para servirlas con la salsa satay y la ensalada.", "Queda muy bien con verduras de raíz asadas, por ejemplo, calabaza, hinojo o betabel. La salsa satay es excelente con pollo.", "Se puede congelar una vez cocido. Descongele en el refrigerador o en el microondas y recaliente bien hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por ración: 3"]),
("ساتاي الخضار", "قوس قزح من الخضار المشوية مع صلصة الفول السوداني الحارة وسلطة عطرية.", "2", "718 غرام",
 ["2 ملعقة صغيرة زيت اللفت", "1 فلفل رومي أحمر، مقطع إلى 6 شرائح", "1 فلفل رومي أخضر، مقطع إلى 6 شرائح", "1 كوسا، مقطعة قطعًا كبيرة", "1 باذنجان، مقطع قطعًا كبيرة", "2 بصلة حمراء مقطعة إلى 6 شرائح", "1 ملعقة صغيرة كمون مطحون", "رشة وفيرة من الفلفل الأسود", "1 بصلة صغيرة، مفرومة", "2 فص ثوم، مهروس", "1 فلفل حار، مفروم ناعمًا", "1 ملعقة صغيرة مكدسة نشا الذرة مذابة في 1 ملعقة كبيرة ماء", "1 ملعقة كبيرة زبدة الفول السوداني", "1 ملعقة صغيرة صلصة صويا قليلة الملح وخالية من الغلوتين", "1 ملعقة صغيرة مُحلٍّ حبيبات", "10 سم خيار، مقطع شرائح رفيعة بحجم أعواد الثقاب", "3 حبات بصل أخضر، مقطعة شرائح رفيعة بحجم أعواد الثقاب", "1 ملعقة كبيرة كزبرة خضراء مفرومة", "½ ليمونة خضراء"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). ضع الزيت على صينية خبز، وأضف الخضار ورشّ الكمون والفلفل وقلّبها جيدًا لتتغطى كل الخضار.", "اخبزها لمدة 30-40 دقيقة، مع تقليبها مرتين أو ثلاثًا خلال ذلك لضمان نضجها بالتساوي.", "في هذه الأثناء، لتحضير صلصة الساتاي ضع البصل في قدر مع الثوم والفلفل الحار و150 مل ماء واتركه حتى يغلي. اتركه على نار هادئة لمدة 5 دقائق حتى يلين البصل. أضف نشا الذرة تدريجيًا مع التحريك المستمر حتى تتكاثف الصلصة. أضف زبدة الفول السوداني وصلصة الصويا والمُحلّي واخلطها حتى تصبح ناعمة.", "للسلطة، اخلط الخيار والبصل الأخضر، ورشّ الكزبرة الخضراء وعصرة من الليمون الأخضر عند التقديم."],
 ["يتضمن التحليل الغذائي أعلاه اقتراح تقديم مع السلطة.", "يمكنك تقطيع الخضار إلى قطع أصغر وتنظيمها على أسياخ وشويها على الشواية أو الفحم وتقديمها مع صلصة الساتاي والسلطة.", "يناسبها جيدًا خضار الجذور المشوية، مثل اليقطين والشمر والشمندر. وصلصة الساتاي رائعة مع الدجاج.", "يمكن تجميده بعد الطهي. ذوّبه في الثلاجة أو الميكروويف وأعد تسخينه جيدًا حتى يصبح ساخنًا جدًا في كل جزء منه.", "حصص الفاكهة/الخضار لكل حصة: 3"])))
R.append((7500982,
("Sopa de papa, poro y queso", "Este plato nutritivo y de mínimo esfuerzo es una excelente opción para un almuerzo rápido.", "2", "363 g",
 ["1 papa grande (aprox. 300 g), picada", "1 poro grande, en rodajas (reserve algunas rodajas para decorar)", "600 ml de caldo de verduras bajo en sal", "50 g de queso crema con la mitad de grasa", "pimienta negra recién molida"],
 ["Ponga la papa, el poro y el caldo en una olla.", "Deje que hierva, tape y cocine a fuego lento durante 15 minutos, hasta que las verduras estén suaves.", "Agregue el queso crema, sazone al gusto y licúe hasta que quede suave. Sirva cubierto con las rodajas de poro."],
 ["Pruebe agregar de 2 a 3 dientes de ajo junto con el poro. No es necesario machacarlos, ya que se licuará el plato.", "Para dar a esta sopa un intenso color verde y una porción extra de verduras, agregue un puñado de chícharos congelados descongelados junto con el queso crema.", "Instrucciones para congelar: Se puede congelar una vez cocida. Descongele por completo y recaliente hasta que esté muy caliente. La sopa puede separarse al congelarse, así que revuelva enérgicamente al recalentar para conservar la consistencia.", "Porciones de fruta/verdura por ración: 1"]),
("حساء البطاطس والكراث والجبن", "هذا الطبق المغذي الذي لا يتطلب جهدًا يُعد خيارًا رائعًا لغداء سريع.", "2", "363 غرام",
 ["1 حبة بطاطس كبيرة (حوالي 300 غرام)، مقطعة", "1 كراث كبير، مقطع شرائح (احتفظ ببعض الشرائح للتزيين)", "600 مل مرق خضار قليل الملح", "50 غرام جبن كريمي نصف دسم", "فلفل أسود مطحون طازجًا"],
 ["ضع البطاطس والكراث والمرق في قدر.", "اتركه حتى يغلي، ثم غطِّه واتركه على نار هادئة لمدة 15 دقيقة حتى تلين الخضار.", "أضف الجبن الكريمي وتبّل حسب الرغبة واخلط حتى يصبح ناعمًا. زيّنه بشرائح الكراث وقدّمه."],
 ["جرّب إضافة 2-3 فصوص من الثوم مع الكراث. لا حاجة لهرسها لأنك ستخلط الطبق.", "لمنح هذا الحساء لونًا أخضر غنيًا وحصة إضافية من الخضار، أضف حفنة من البازلاء المجمدة المذوّبة مع الجبن الكريمي.", "تعليمات التجميد: يمكن تجميده بعد الطهي. ذوّبه تمامًا وأعد تسخينه حتى يصبح ساخنًا جدًا. قد ينفصل الحساء أثناء التجميد، لذا حرّكه بقوة عند إعادة التسخين للحفاظ على قوامه.", "حصص الفاكهة/الخضار لكل حصة: 1"])))
R.append((7504418,
("Quesadillas de bistec y pimiento", "Sirva unos sabrosos wraps mexicanos en su próxima cena familiar.", "4", "220 g",
 ["Aceite en aerosol para cocinar controlado en calorías", "175 g de bistec magro y delgado", "1 pimiento rojo y 1 amarillo, sin semillas y en rebanadas", "1 cebolla morada, en rebanadas", "1 diente de ajo, finamente picado", "½ cucharadita de hojuelas de chile seco", "50 g de queso cheddar con la mitad de grasa, rallado", "Un puñado de hojas de cilantro fresco", "4 wraps WW*"],
 ["Rocíe una sartén con el aceite en aerosol y colóquela a fuego medio. Cocine el bistec al menos 2 minutos por cada lado.", "Rocíe la sartén de nuevo y cocine los pimientos y la cebolla de 6 a 8 minutos. Agregue el ajo y el chile y cocine 1 minuto. Corte el bistec en tiras y mézclelo con los pimientos y la cebolla.", "Esparza la mitad del queso sobre 2 wraps. Cubra con el bistec y las verduras, luego con el queso restante y el cilantro. Presione suavemente 2 wraps más encima. Rocíe la sartén de nuevo y colóquela a fuego medio. Cocine uno a la vez de 3 a 4 minutos por cada lado, rociando la sartén cada vez. Corte en cuartos y sirva."],
 ["*Puede usar cualquier wrap de su elección, pero recuerde que el contenido de carbohidratos puede variar de un producto a otro."]),
("كساديا شرائح اللحم والفلفل", "قدّم بعض اللفائف المكسيكية اللذيذة في عشاء عائلتك القادم.", "4", "220 غرام",
 ["بخاخ طهي مضبوط السعرات", "175 غرام ستيك قليل الدسم رقيق الشرائح", "1 فلفل رومي أحمر و1 أصفر، منزوع البذور ومقطع شرائح", "1 بصلة حمراء، مقطعة شرائح", "1 فص ثوم، مفروم ناعمًا", "½ ملعقة صغيرة رقائق فلفل حار مجفف", "50 غرام جبن شيدر نصف دسم، مبشور", "حفنة أوراق كزبرة خضراء طازجة", "4 لفائف WW*"],
 ["رشّ مقلاة ببخاخ الطهي وضعها على نار متوسطة. اطه الستيك لمدة 2 دقيقة على الأقل من كل جهة.", "رشّ المقلاة مرة أخرى، واطه الفلفل الرومي والبصل لمدة 6-8 دقائق. أضف الثوم والفلفل الحار واطهها لمدة 1 دقيقة. قطّع الستيك إلى شرائح واخلطه مع الفلفل الرومي والبصل.", "انثر نصف الجبن على 2 لفافة. ضع فوقهما الستيك والخضار، ثم الجبن المتبقي والكزبرة. اضغط برفق 2 لفافة أخرى فوقهما. رشّ المقلاة مرة أخرى وضعها على نار متوسطة. اطه واحدة في كل مرة لمدة 3-4 دقائق من كل جهة، مع رشّ المقلاة في كل مرة. قطّعها إلى أرباع وقدّمها."],
 ["*يمكنك استخدام أي لفافة تختارها، لكن تذكّر أن محتوى الكربوهيدرات قد يختلف من منتج إلى آخر."])))
R.append((7505781,
("Sopa picante de calabaza butternut", "Esta deliciosa sopa es reconfortante y tiene un toque picante.", "4", "380 g",
 ["1 cucharada de aceite de colza", "1 cebolla, picada", "de medio a 1 chile rojo, picado", "1 diente de ajo, machacado", "2 calabazas butternut medianas, peladas, sin semillas y picadas", "1 cucharada de pasta de curry de sabor medio", "1 cubito de caldo de verduras bajo en sal", "200 ml de leche de coco reducida en grasa", "2 cucharadas de cilantro fresco, picado", "pimienta negra recién molida, para servir", "rodajas de chile y hojas de cilantro, para decorar"],
 ["Caliente el aceite en una cacerola. Agregue la cebolla, el chile y el ajo, y fría de 4 a 5 minutos hasta que se ablanden.", "Agregue la calabaza y siga friendo durante 5 minutos. Incorpore la pasta de curry y fría 1 minuto más.", "Vierta 500 ml de agua hirviendo sobre la calabaza, desmenuce el cubito de caldo y deje que hierva. Tape y cocine a fuego lento de 15 a 20 minutos, hasta que la calabaza esté tierna. Pase a un procesador de alimentos o licuadora y licúe hasta que quede suave.", "Regrese a la cacerola, agregue la leche de coco y el cilantro. Caliente bien y sirva espolvoreada con pimienta negra. Decore con una rodaja de chile y hojas de cilantro desgarradas."],
 ["Si no le gusta demasiado picante, omita el chile y use una pasta o polvo de curry suave en su lugar.", "Puede preparar esta sopa con camote en lugar de calabaza butternut.", "Instrucciones para congelar: Congele en porciones y luego descongele en el refrigerador, o descongele en el microondas cuidando de revolver con frecuencia.", "Porciones de fruta/verdura por ración: 3"]),
("حساء اليقطين الجوزي الحار", "هذا الحساء اللذيذ دافئ وبنكهة حارة منعشة.", "4", "380 غرام",
 ["1 ملعقة كبيرة زيت اللفت", "1 بصلة، مفرومة", "½ إلى 1 فلفل حار أحمر، مفروم", "1 فص ثوم، مهروس", "2 يقطين جوزي متوسط، مقشر ومنزوع البذور ومقطع", "1 ملعقة كبيرة معجون كاري متوسط الحدة", "1 مكعب مرق خضار قليل الملح", "200 مل حليب جوز الهند قليل الدسم", "2 ملعقة كبيرة كزبرة خضراء طازجة، مفرومة", "فلفل أسود مطحون طازجًا، للتقديم", "شرائح فلفل حار وأوراق كزبرة خضراء، للتزيين"],
 ["سخّن الزيت في قدر. أضف البصل والفلفل الحار والثوم وقلّبها على النار لمدة 4-5 دقائق حتى تلين.", "أضف اليقطين واستمر في التقليب لمدة 5 دقائق. أضف معجون الكاري وقلّب دقيقة أخرى.", "صبّ 500 مل ماء مغلي على اليقطين، وفتّت مكعب المرق فيه واتركه حتى يغلي. غطِّه واتركه على نار هادئة لمدة 15-20 دقيقة حتى يصبح اليقطين طريًا. انقله إلى محضّر الطعام أو الخلاط واخلطه حتى يصبح ناعمًا.", "أعده إلى القدر، وأضف حليب جوز الهند والكزبرة الخضراء. سخّنه جيدًا وقدّمه مرشوشًا بالفلفل الأسود. زيّنه بشريحة من الفلفل الحار وأوراق الكزبرة الخضراء الممزقة."],
 ["إذا كنت لا تحب الأطعمة الحارة جدًا، فاحذف الفلفل الحار واستخدم معجون أو مسحوق كاري معتدل بدلًا منه.", "يمكنك تحضير هذا الحساء بالبطاطا الحلوة بدلًا من اليقطين الجوزي.", "تعليمات التجميد: جمّده في حصص ثم ذوّبه في الثلاجة، أو ذوّبه في الميكروويف مع الحرص على التحريك بانتظام.", "حصص الفاكهة/الخضار لكل حصة: 3"])))
R.append((7511563,
("Rundown de caballa", "Este sabroso guiso es un clásico de la cocina jamaiquina.", "4", "349 g",
 ["1 cucharadita de aceite de oliva", "1 cebolla grande, pelada y en cubos", "2 dientes de ajo grandes, pelados y machacados", "1 cucharadita de hojas de tomillo fresco", "1 cucharadita de pimentón dulce", "1 cucharadita de comino molido", "200 ml de leche de coco ligera", "2 tomates maduros, picados", "1 pimiento rojo, sin corazón ni semillas, en trozos", "1 pimiento amarillo, sin corazón ni semillas, en trozos", "1 chile scotch bonnet", "3 filetes de caballa (de unos 90 g cada uno)", "Un pequeño puñado de perejil liso fresco (opcional)"],
 ["Caliente el aceite en una cacerola grande y fría la cebolla a fuego lento de 4 a 5 minutos hasta que esté suave pero sin dorarse. Incorpore el ajo, el tomillo, el pimentón y el comino, y fría de 30 a 40 segundos revolviendo continuamente hasta que suelten su aroma.", "Agregue la leche de coco, 200 ml de agua, los tomates, los pimientos y la calabaza butternut, y mezcle bien.", "Pinche el chile varias veces con un cuchillo afilado y luego empújelo bajo la superficie de la leche de coco. Deje que hierva y luego cocine a fuego lento sin tapar durante 15 minutos.", "Corte cada filete de caballa en cuatro o cinco trozos y espárzalos sobre la salsa. Tape y cocine a fuego lento 10 minutos más, hasta que el pescado esté bien cocido por completo.", "Deseche el scotch bonnet o, si se siente valiente, deseche el tallo y las semillas, haga puré la pulpa y vuelva a incorporarla al guiso. Esparza el perejil si lo desea y sirva de inmediato."],
 ["Porciones de fruta/verdura por ración: 2"]),
("ماكريل رندوان", "هذه اليخنة المليئة بالنكهة طبق كلاسيكي في المطبخ الجامايكي.", "4", "349 غرام",
 ["1 ملعقة صغيرة زيت زيتون", "1 بصلة كبيرة، مقشرة ومقطعة مكعبات", "2 فص ثوم كبير، مقشر ومهروس", "1 ملعقة صغيرة أوراق زعتر طازجة", "1 ملعقة صغيرة بابريكا", "1 ملعقة صغيرة كمون مطحون", "200 مل حليب جوز الهند الخفيف", "2 حبة طماطم ناضجة، مقطعة", "1 فلفل رومي أحمر، منزوع القلب والبذور ومقطع قطعًا كبيرة", "1 فلفل رومي أصفر، منزوع القلب والبذور ومقطع قطعًا كبيرة", "1 فلفل سكوتش بونيت", "3 شرائح فيليه سمك الماكريل (حوالي 90 غرام لكل واحدة)", "حفنة صغيرة من البقدونس المسطح الطازج (اختياري)"],
 ["سخّن الزيت في قدر كبير وقلِّ البصل على نار هادئة لمدة 4-5 دقائق حتى يلين دون أن يتلوّن. أضف الثوم والزعتر والبابريكا والكمون وقلّب لمدة 30-40 ثانية مع التحريك المستمر حتى تفوح رائحتها.", "أضف حليب جوز الهند و200 مل ماء والطماطم والفلفل الرومي واليقطين الجوزي وحرّك جيدًا.", "اغرز الفلفل الحار عدة مرات بسكين حاد ثم ادفعه تحت سطح حليب جوز الهند. اتركه حتى يغلي، ثم اتركه على نار هادئة دون غطاء لمدة 15 دقيقة.", "قطّع كل شريحة ماكريل إلى أربع أو خمس قطع وانثرها فوق الصلصة. غطِّه واتركه على نار هادئة لمدة 10 دقائق أخرى حتى ينضج السمك تمامًا.", "تخلّص من فلفل سكوتش بونيت، أو إذا كنت جريئًا فتخلّص من الساق والبذور واهرس اللب وأعده إلى اليخنة. انثر البقدونس إن شئت وقدّمه فورًا."],
 ["حصص الفاكهة/الخضار لكل حصة: 2"])))
R.append((7511962,
("Pan de plátano", "Ponga una rebanada de este pan frutal en su almuerzo para llevar.", "12", "58 g",
 ["2 plátanos grandes (250 g sin cáscara)", "2 huevos de gallinas camperas", "4 cucharadas de aceite de colza", "1 cucharadita de extracto de vainilla", "100 g de azúcar morena clara suave", "150 g de harina integral", "2 cucharaditas de polvo para hornear", "1 cucharadita colmada de mezcla de especias dulces (mixed spice)", "50 g de nueces, picadas en trozos grandes (reserve unas cuantas enteras para poner encima)"],
 ["Precaliente el horno a 170 °C (marca de gas 3). Triture los plátanos, luego agregue los huevos y bata juntos.", "Agregue el aceite, el extracto de vainilla y el azúcar, y mezcle bien.", "Incorpore la harina, el polvo para hornear y la mezcla de especias; luego integre con movimientos envolventes las nueces picadas.", "Vierta con una cuchara en un molde para pan de 2 libras (aprox. 22 x 11 cm), coloque las nueces enteras encima y hornee durante unos 50 a 55 minutos, hasta que un palillo largo insertado en el centro salga limpio.", "Deje enfriar en el molde durante 10 minutos antes de desmoldar sobre una rejilla para que se enfríe por completo."],
 ["Puede agregar otras especias a esta mezcla, como jengibre molido o canela, o usar almendras o semillas de girasol en lugar de nueces.", "Instrucciones para congelar: Se puede congelar una vez horneado. Corte en rebanadas y envuelva en papel de aluminio para congelar. Luego puede usar las rebanadas según lo necesite."]),
("خبز الموز", "ضع شريحة من هذه الكعكة بالفاكهة في وجبة غدائك المحمولة.", "12", "58 غرام",
 ["2 موزة كبيرة (250 غرام وزن بعد التقشير)", "2 بيضة من دجاج حر", "4 ملاعق كبيرة زيت اللفت", "1 ملعقة صغيرة مستخلص الفانيليا", "100 غرام سكر بني فاتح ناعم", "150 غرام دقيق قمح كامل", "2 ملعقة صغيرة بيكنج بودر", "1 ملعقة صغيرة مكدسة توابل مشكلة حلوة (ميكسد سبايس)", "50 غرام جوز، مفروم فرمًا خشنًا (مع الاحتفاظ ببضع حبات كاملة لوضعها في الأعلى)"],
 ["سخّن الفرن مسبقًا إلى 170° مئوية (علامة الغاز 3). اهرس الموز، ثم أضف البيض واخفقهما معًا.", "أضف الزيت ومستخلص الفانيليا والسكر واخلط جيدًا.", "أضف الدقيق والبيكنج بودر والتوابل المشكلة وحرّك، ثم اطوِ فيه الجوز المفروم.", "اسكب الخليط بالملعقة في قالب خبز سعة 2 رطل (حوالي 22 × 11 سم)، وضع حبات الجوز الكاملة في الأعلى، واخبزه لمدة 50-55 دقيقة تقريبًا حتى يخرج سيخ مغروس في المنتصف نظيفًا.", "اتركه يبرد في القالب لمدة 10 دقائق قبل قلبه على رف ليبرد تمامًا."],
 ["يمكنك إضافة توابل أخرى إلى هذا الخليط مثل الزنجبيل المطحون أو القرفة، أو استخدام اللوز أو بذور عباد الشمس بدلًا من الجوز.", "تعليمات التجميد: يمكن تجميده بعد الخبز. قطّعه إلى شرائح ثم لفّه في ورق الألمنيوم للتجميد. يمكنك بعد ذلك استخدام الشرائح حسب الحاجة."])))
R.append((7512154,
("Mini pasteles de calabaza en masa filo", "Calabaza especiada servida en canastillas de masa filo y cubierta con semillas de calabaza y ralladura de naranja.", "12", "57 g",
 ["8 hojas de masa filo (en cuadros de 24x8 cm, 40 g cada una)", "6 rociadas de aceite", "200 g de calabaza o calabaza butternut, pelada y cortada en cubos pequeños", "2 cucharaditas de edulcorante granulado (opcional)", "2 huevos, batidos", "media cucharadita de nuez moscada", "media cucharadita de canela", "media cucharadita de jengibre molido", "una pizca de clavo de olor molido", "2 cucharadas de yogur griego sin grasa (0 %)", "10 g de semillas de calabaza", "ralladura de 1 naranja"],
 ["Precaliente el horno a 180 °C (marca de gas 4). Engrase ligeramente un molde poco profundo para panquecitos.", "Corte la masa filo en cuadros de 8 cm y rocíe un poco de aceite en un lado. Coloque un cuadro de filo en cada cavidad del molde. Rocíe más cuadros con aceite y colóquelos encima. Repita para que cada cavidad tenga tres capas de masa.", "Mientras tanto, prepare el relleno mezclando los huevos, la calabaza, el yogur y las especias en un tazón grande.", "Ponga el relleno en las canastillas de masa y hornee de 10 a 12 minutos, hasta que la canastilla de filo esté ligeramente dorada y la calabaza todavía se sienta un poco temblorosa en el centro. Cubra con las semillas de calabaza y la ralladura de naranja para servir."],
 ["Si lo prefiere, puede hacer un solo pastel grande: forre un molde para hornear con la masa filo y deje de 8 a 10 minutos adicionales de cocción.", "Porciones de fruta/verdura por ración: 0"]),
("فطائر اليقطين الصغيرة بعجينة الفيلو", "يقطين متبّل يُكدَّس في سلال من عجينة الفيلو ويُزيَّن ببذور اليقطين وبشر البرتقال.", "12", "57 غرام",
 ["8 ورقات عجين فيلو (مربعات 24×8 سم، 40 غرام لكل واحدة)", "6 رشات زيت", "200 غرام يقطين أو يقطين جوزي، مقشر ومقطع مكعبات صغيرة", "2 ملعقة صغيرة مُحلٍّ حبيبات (اختياري)", "2 بيضة، مخفوقة", "½ ملعقة صغيرة جوزة الطيب", "½ ملعقة صغيرة قرفة", "½ ملعقة صغيرة زنجبيل مطحون", "رشة قرنفل مطحون", "2 ملعقة كبيرة زبادي يوناني خالٍ من الدسم 0%", "10 غرام بذور يقطين", "بشر قشر 1 برتقالة"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). ادهن قالب مافن ضحل بقليل من الزيت.", "قطّع عجينة الفيلو إلى مربعات 8 سم ورشّ قليلًا من الزيت على أحد الوجهين. ضع مربعًا من الفيلو في كل تجويف من قالب المافن. رشّ مربعات أخرى بالزيت وضعها فوقها. كرّر حتى يحتوي كل تجويف على ثلاث طبقات من العجين.", "في هذه الأثناء، حضّر الحشوة بخلط البيض واليقطين والزبادي والتوابل في وعاء كبير.", "ضع الحشوة في قوالب العجين واخبزها لمدة 10-12 دقيقة حتى تتحمّر سلة الفيلو قليلًا ويبقى اليقطين مهتزًا قليلًا في المنتصف. زيّنها ببذور اليقطين وبشر البرتقال عند التقديم."],
 ["إذا فضّلت، يمكنك تحضير فطيرة كبيرة واحدة، بتبطين قالب خبز بعجينة الفيلو مع إضافة 8-10 دقائق أخرى لوقت الطهي.", "حصص الفاكهة/الخضار لكل حصة: 0"])))
R.append((7516891,
("Salteado oriental de res", "Rápido y fácil de preparar, y lleno de sabor y de verduras sabrosas, esta receta es perfecta si desea una comida saludable al instante.", "4", "323 g",
 ["2 cucharaditas de aceite vegetal", "400 g de bistec de res magro (cuadril o lomo)", "4 dientes de ajo, machacados", "2 pimientos amarillos o rojos, sin semillas y en rebanadas", "200 g de brócoli, cortado en ramilletes pequeños", "4 cebollines, en rodajas", "2 pak choi (bok choy), en rodajas", "1 lata pequeña (200 g) de castañas de agua, escurridas y en rodajas", "2 cucharadas de salsa de ostras"],
 ["Caliente el aceite en una sartén antiadherente o wok. Quite la grasa del bistec, córtelo en tiras finas y agréguelo a la sartén.", "Saltee de 1 a 2 minutos para sellar, agregue el ajo, los pimientos, los ramilletes de brócoli y los cebollines, junto con 2 cucharadas de agua.", "Saltee durante 3 minutos, agregue el pak choi, las castañas de agua y la salsa de ostras. Deje que se caliente bien y sirva de inmediato."],
 ["Puede usar cerdo magro o pollo en lugar de res.", "Para una versión vegetariana, use tofu firme cortado en tiras. Fría de 3 a 4 minutos por cada lado y retire de la sartén, cocine el resto de los ingredientes, vuelva a agregar el tofu, mezcle bien y sirva.", "Porciones de fruta/verdura por ración: 2"]),
("لحم بقري مقلي على الطريقة الشرقية", "سريع وسهل التحضير ومليء بالنكهة والخضار اللذيذة، وهذه الوصفة مثالية إذا أردت وجبة صحية على الفور.", "4", "323 غرام",
 ["2 ملعقة صغيرة زيت نباتي", "400 غرام ستيك لحم بقري قليل الدسم (من الردف أو الخاصرة)", "4 فص ثوم، مهروس", "2 فلفل رومي أصفر أو أحمر، منزوع البذور ومقطع شرائح", "200 غرام بروكلي، مقطع زهيرات صغيرة", "4 حبات بصل أخضر، مقطعة", "2 باك تشوي (بوك تشوي)، مقطع", "1 علبة صغيرة (200 غرام) كستناء مائية، مصفاة ومقطعة شرائح", "2 ملعقة كبيرة صلصة المحار"],
 ["سخّن الزيت في مقلاة غير لاصقة أو ووك. انزع أي دهون عن الستيك وقطّعه إلى شرائح رفيعة وأضفه إلى المقلاة.", "قلّبه على نار عالية لمدة 1-2 دقيقة لإغلاق مسامه، ثم أضف الثوم والفلفل الرومي وزهيرات البروكلي والبصل الأخضر مع 2 ملعقة كبيرة ماء.", "قلّبها لمدة 3 دقائق، ثم أضف الباك تشوي والكستناء المائية وصلصة المحار. اتركها لتسخن جيدًا تمامًا وقدّمها فورًا."],
 ["يمكنك استخدام لحم الخنزير قليل الدسم أو الدجاج بدلًا من لحم البقر.", "للحصول على نسخة نباتية، استخدم التوفو الصلب المقطع إلى شرائح. قلِه لمدة 3-4 دقائق من كل جهة ثم أخرجه من المقلاة، واطه بقية المكونات، وأعد التوفو إلى المقلاة، واخلط جيدًا وقدّمه.", "حصص الفاكهة/الخضار لكل حصة: 2"])))
R.append((7519383,
("Sopa cremosa de pollo y champiñones", "Una combinación tradicional de sopa, más baja en grasa, que toda la familia puede disfrutar.", "4", "301 g",
 ["2 cucharaditas de aceite", "2 cebollas, picadas", "2 pechugas de pollo sin piel (aprox. 200 g), picadas en trozos pequeños", "250 g de champiñones", "2 dientes de ajo, machacados", "1 cubito de caldo de pollo, disuelto en 500 ml de agua", "1 cucharadita colmada de maicena", "una buena pizca de pimienta blanca", "300 ml de leche descremada", "100 g de yogur griego sin grasa (0 %)", "2 cucharaditas de cebollín picado", "un poco de pimienta negra molida"],
 ["Ponga el aceite en una olla y cocine las cebollas suavemente durante 5 minutos, revolviendo con frecuencia.", "Agregue el pollo y revuelva durante 2 a 3 minutos.", "Agregue los champiñones y el ajo y cocine de 2 a 3 minutos más.", "Agregue el caldo, mezcle bien, deje que hierva, baje el fuego, tape con la tapa y cocine a fuego lento durante 15 minutos.", "En una jarra, mezcle la maicena y la pimienta blanca e incorpore la leche.", "Incorpore poco a poco la mezcla de leche y maicena al pollo y los champiñones, revolviendo constantemente, y lleve casi al punto de ebullición.", "Incorpore el yogur, retire del fuego y licúe la mezcla hasta que quede suave. Sirva espolvoreada con el cebollín y la pimienta negra."],
 ["Puede usar una licuadora de inmersión o una licuadora de vaso.", "Pruebe agregar hierbas como estragón, perejil o albahaca frescos. Dele un toque picante con 1 cucharadita de comino molido.", "Instrucciones para congelar: Se puede congelar en recipientes pequeños para porciones individuales. Descongele en el microondas o a fuego muy bajo hasta que esté muy caliente.", "Porciones de fruta/verdura por ración: 1"]),
("حساء الدجاج والفطر الكريمي", "تشكيلة حساء تقليدية أقل دسمًا يمكن لجميع أفراد العائلة الاستمتاع بها.", "4", "301 غرام",
 ["2 ملعقة صغيرة زيت", "2 بصلة، مفرومة", "2 صدر دجاج بدون جلد (حوالي 200 غرام)، مقطع قطعًا صغيرة", "250 غرام فطر", "2 فص ثوم، مهروس", "1 مكعب مرق دجاج، مذاب في 500 مل ماء", "1 ملعقة صغيرة مكدسة نشا الذرة", "رشة وفيرة من الفلفل الأبيض", "300 مل حليب خالي الدسم", "100 غرام زبادي يوناني خالٍ من الدسم 0%", "2 ملعقة صغيرة ثوم معمر (شيفز) مفروم", "رشة فلفل أسود مطحون"],
 ["ضع الزيت في قدر واطه البصل بهدوء لمدة 5 دقائق مع التحريك باستمرار.", "أضف الدجاج وقلّب لمدة 2-3 دقائق.", "أضف الفطر والثوم واطهها لمدة 2-3 دقائق أخرى.", "أضف المرق وحرّك جيدًا، واتركه حتى يغلي، ثم خفّض النار وغطِّه بالغطاء واتركه على نار هادئة لمدة 15 دقيقة.", "في إبريق، اخلط نشا الذرة والفلفل الأبيض معًا وأضف الحليب مع التحريك.", "أضف خليط الحليب والنشا تدريجيًا إلى الدجاج والفطر مع التحريك المستمر، ثم أوصله إلى ما يقارب درجة الغليان.", "أضف الزبادي وحرّك، وارفعه عن النار واخلط الخليط حتى يصبح ناعمًا. قدّمه مرشوشًا بالثوم المعمر والفلفل الأسود."],
 ["يمكنك استخدام خلاط يدوي أو خلاط عادي.", "جرّب إضافة أعشاب مثل الطرخون أو البقدونس أو الريحان الطازج. أضف عليه نكهة حارة بـ1 ملعقة صغيرة كمون مطحون.", "تعليمات التجميد: يمكن تجميده في أوعية صغيرة لحصص فردية. ذوّبه في الميكروويف أو على نار هادئة جدًا حتى يصبح ساخنًا جدًا.", "حصص الفاكهة/الخضار لكل حصة: 1"])))
R.append((7520378,
("Pasta in brodo", "Un excelente plato para aprovechar pasta seca rota y las verduras que prefiera.", "2", "484 g",
 ["120 g de pasta integral en formas variadas (peso en seco)", "1 cucharada de aceite de oliva", "1 cebolla, finamente picada", "1 pimiento amarillo, picado", "1 zanahoria, en cubos", "300 ml de caldo de verduras, o 500 ml de caldo de verduras reducido en sal", "1 cucharadita colmada de orégano seco", "2 tomates de rama grandes, picados", "50 g de edamames congelados frescos, descongelados", "2 hojas de repollo, picadas", "2 cucharaditas de pesto", "10 g de queso parmesano, para servir"],
 ["Ponga la pasta en una olla con agua hirviendo, cocine durante 8 minutos y escurra.", "Mientras tanto, ponga el aceite de oliva en una olla y agregue la cebolla, el pimiento amarillo y la zanahoria. Revuelva con frecuencia durante 5 minutos, hasta que empiecen a dorarse.", "Agregue el caldo y el orégano, deje que hierva, luego baje el fuego y agregue los edamames y el repollo. Vuelva a llevar a un hervor suave, revolviendo con frecuencia durante 2 minutos.", "Agregue la pasta, vuelva a llevar a un hervor suave y luego retire del fuego.", "Reparta en dos tazones y agregue una cucharada de pesto a cada uno. Para servir, espolvoree con abundante pimienta negra y un poco de queso parmesano."],
 ["Es ideal para aprovechar cualquier pasta seca rota y casi cualquier verdura.", "Elija un caldo reducido en sal para disminuir la sal de este plato, o prepare el suyo propio.", "Instrucciones para congelar: Se puede congelar una vez cocido. Luego descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por ración: 4"]),
("باستا إن برودو", "طبق رائع للاستفادة من المعكرونة الجافة المكسّرة وأي خضار تحبها.", "2", "484 غرام",
 ["120 غرام معكرونة قمح كامل بأشكال متنوعة (الوزن جافة)", "1 ملعقة كبيرة زيت زيتون", "1 بصلة، مفرومة ناعمًا", "1 فلفل رومي أصفر، مقطع", "1 جزرة، مقطعة مكعبات", "300 مل مرق خضار، أو 500 مل مرق خضار قليل الملح", "1 ملعقة صغيرة مكدسة أوريجانو مجفف", "2 حبة طماطم عنقودية كبيرة، مقطعة", "50 غرام إدامامي (فول الصويا الأخضر) طازج مجمد، مذوّب", "2 ورقة ملفوف، مقطعة", "2 ملعقة صغيرة بيستو", "10 غرام جبن بارميزان، للتقديم"],
 ["ضع المعكرونة في قدر من الماء المغلي، واطهها لمدة 8 دقائق ثم صفّها.", "في هذه الأثناء، ضع زيت الزيتون في قدر وأضف البصل والفلفل الرومي الأصفر والجزر. قلّبها باستمرار لمدة 5 دقائق حتى تبدأ في التحمير.", "أضف المرق والأوريجانو واتركه حتى يغلي، ثم خفّض النار وأضف الإدامامي والملفوف. أعده إلى غليان خفيف مع التحريك باستمرار لمدة 2 دقيقة.", "أضف المعكرونة وأعده إلى غليان خفيف مرة أخرى، ثم ارفعه عن النار.", "وزّعه على وعاءين وأضف كتلة من البيستو إلى كل منهما. وللتقديم، رشّ الكثير من الفلفل الأسود وقليلًا من جبن البارميزان."],
 ["هذا الطبق رائع للاستفادة من أي معكرونة جافة مكسّرة وأي خضار تقريبًا.", "اختر مرقًا قليل الملح لتقليل الملح في هذا الطبق، أو حضّر مرقك بنفسك.", "تعليمات التجميد: يمكن تجميده بعد الطهي. ثم ذوّبه في الثلاجة أو الميكروويف وأعد تسخينه حتى يصبح ساخنًا جدًا في كل جزء منه.", "حصص الفاكهة/الخضار لكل حصة: 4"])))
R.append((7521021,
("Pastel de betabel y zanahoria", "La piña y el jugo de piña dan un toque extra de sabor a este pastel de betabel y zanahoria.", "10", "100 g",
 ["200 g de harina integral común", "2 cucharaditas de polvo para hornear", "1 cucharadita de bicarbonato de sodio", "1 cucharadita de canela molida", "100 g de betabel crudo rallado", "100 g de zanahoria rallada, exprimida", "4 huevos", "100 g de azúcar refinada fina", "1 lata de 435 g de piña triturada en jugo", "1 cucharada de azúcar glas"],
 ["Precaliente el horno a 150 °C (marca de gas 2). Engrase y forre un molde para pastel de 20 cm de base desmontable.", "Tamice la harina, el polvo para hornear, el bicarbonato y la canela en un tazón grande. Agregue el betabel y la mitad de la zanahoria, y mezcle de manera uniforme. Ponga 2 claras de huevo en un tazón y bata hasta formar picos suaves. Ponga las yemas restantes y los huevos enteros en un tazón con el azúcar refinada y bata con una batidora eléctrica de 4 a 5 minutos hasta que estén pálidos y espesos.", "Escurra el jugo de la piña en una cacerola. Pique la piña y agréguela, junto con las claras y los huevos batidos, a la mezcla de harina e integre con movimientos envolventes hasta que esté uniforme. Vierta con una cuchara en el molde. Esparza la zanahoria restante y espolvoree con el azúcar glas.", "Hornee durante 75 minutos, luego cubra con papel de aluminio y hornee 15 minutos más, o hasta que un palillo largo insertado en el centro salga limpio. Desmolde sobre una rejilla y deje enfriar.", "Cocine a fuego lento el jugo de piña de 5 a 6 minutos hasta que adquiera consistencia de almíbar. Rocíe sobre el pastel tibio y deje enfriar."],
 []),
("كعكة الشمندر والجزر", "يمنح الأناناس وعصير الأناناس هذه الكعكة بالشمندر والجزر نكهة منعشة إضافية.", "10", "100 غرام",
 ["200 غرام دقيق قمح كامل عادي", "2 ملعقة صغيرة بيكنج بودر", "1 ملعقة صغيرة بيكربونات الصوديوم (صودا الخبز)", "1 ملعقة صغيرة قرفة مطحونة", "100 غرام شمندر نيئ مبشور", "100 غرام جزر مبشور، معصور حتى يجف", "4 بيضات", "100 غرام سكر ناعم", "1 علبة 435 غرام أناناس مهروس في عصيره", "1 ملعقة كبيرة سكر بودرة"],
 ["سخّن الفرن مسبقًا إلى 150° مئوية (علامة الغاز 2). ادهن قالب كعك قطره 20 سم بقاعدة منفصلة بالزيت وبطّنه.", "اغربل الدقيق والبيكنج بودر وبيكربونات الصوديوم والقرفة في وعاء كبير. أضف الشمندر ونصف كمية الجزر واخلط بالتساوي. ضع بياض 2 بيضة في وعاء واخفقه حتى تتكون قمم لينة. ضع الصفار المتبقي والبيض الكامل في وعاء مع السكر الناعم واخفقها بمضرب كهربائي لمدة 4-5 دقائق حتى يصبح الخليط شاحبًا وكثيفًا.", "صفّ عصير الأناناس في قدر. قطّع الأناناس وأضفه مع بياض البيض والبيض المخفوق إلى خليط الدقيق واطوِ برفق حتى يتجانس الخليط. اسكبه بالملعقة في قالب الكعك. انثر باقي الجزر وزيّنها بالسكر البودرة.", "اخبزها لمدة 75 دقيقة، ثم غطِّها بورق الألمنيوم واخبزها 15 دقيقة أخرى أو حتى يخرج سيخ مغروس في المنتصف نظيفًا. اقلبها على رف شبكي واتركها لتبرد.", "اترك عصير الأناناس على نار هادئة لمدة 5-6 دقائق حتى يصبح بقوام الشراب. اسكبه على الكعكة وهي دافئة واتركها لتبرد."],
 [])))
R.append((7521301,
("Sopa dorada", "«Esta receta es como unas vacaciones en un tazón. A mis hijos también les encanta, y es tan fácil de preparar que las ‘manitas’ pueden ayudar con las verduras. La llamo ‘sopa dorada’ porque al licuarla parece oro líquido».", "6", "290 g",
 ["1 cebolla morada", "1 cebolla blanca", "1 pimiento rojo", "2 pimientos amarillos/anaranjados", "2 calabacines grandes o 4 pequeños", "2 tomates", "una pizca de hierbas secas mixtas", "1 cucharadita colmada de levadura nutricional", "aceite en aerosol (opcional)", "1 cubito de caldo bajo en sal (opcional)", "500 ml de agua hirviendo"],
 ["Precaliente el horno a 180 °C (160 °C con ventilador) / 350 °F / marca de gas 4.", "Corte todas las verduras en trozos, espolvoree con las hierbas secas mixtas y la levadura nutricional, y rocíe con el aceite de su elección para acelerar el proceso de asado. A menudo asó sin aceite y las verduras se asan bien y conservan su humedad. Colóquelas en el centro del horno de 25 a 30 minutos, hasta que las verduras estén doradas y tostadas en los bordes.", "Disuelva el cubito de caldo en el agua caliente, listo para agregarlo a la licuadora.", "Ponga las verduras asadas, el agua y el caldo en una licuadora y licúe hasta que quede suave. Vierta en una olla y mantenga caliente. Rectifique la sazón y sirva."],
 ["Esta receta fue creada por Shivali, la protagonista de la portada de Balance, como parte de su camino hacia la remisión de la diabetes.", "Porciones de fruta/verdura por ración: 2"]),
("الحساء الذهبي", "«تبدو هذه الوصفة كعطلة في وعاء. يحبها أطفالي أيضًا، وهي سهلة التحضير لدرجة أن «الأيدي الصغيرة» تستطيع المساعدة في الخضار. أسميها «الحساء الذهبي» لأنه عند خلطه يبدو كالذهب السائل».", "6", "290 غرام",
 ["1 بصلة حمراء", "1 بصلة بيضاء", "1 فلفل رومي أحمر", "2 فلفل رومي أصفر/برتقالي", "2 كوسا كبيرة أو 4 صغيرة", "2 حبة طماطم", "رشة أعشاب مجففة مشكلة", "1 ملعقة صغيرة مكدسة خميرة غذائية", "بخاخ زيت (اختياري)", "1 مكعب مرق قليل الملح (اختياري)", "500 مل ماء مغلي"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (160° مئوية للفرن بمروحة) / 350° فهرنهايت (175° مئوية) / علامة الغاز 4.", "قطّع جميع الخضار إلى قطع، ورشّ عليها الأعشاب المجففة المشكلة والخميرة الغذائية، ورشّها بالزيت الذي تختاره لتسريع عملية الشوي. كثيرًا ما أشويها دون زيت فتنضج الخضار جيدًا وتحتفظ برطوبتها. ضعها في وسط الفرن لمدة 25-30 دقيقة حتى تكتسب الخضار لونًا برونزيًا ومحمرًّا عند الحواف.", "حرّك مكعب المرق في الماء الدافئ استعدادًا لإضافته إلى الخلاط.", "ضع الخضار المشوية والماء والمرق في الخلاط واخلطها حتى تصبح ناعمة. اسكبها في قدر وأبقها دافئة. تحقق من التتبيل وقدّم."],
 ["ابتكرت هذه الوصفة شيفالي، نجمة غلاف مجلة Balance، ضمن رحلتها نحو شفاء مرض السكري.", "حصص الفاكهة/الخضار لكل حصة: 2"])))
R.append((7522633,
("Risotto de pollo con verduras de primavera", "Una cena de todos los días llena de nutrientes.", "4", "293 g",
 ["1 cucharadita de aceite de oliva", "1 cebolla pequeña, finamente picada", "1 diente de ajo, machacado", "2 pechugas de pollo deshuesadas y sin piel, en cubos", "225 g de arroz para risotto", "1 litro de caldo de pollo caliente", "1 paquete de 100 g de espárragos, cortados por la mitad", "150 g de chícharos congelados", "2 cucharadas de queso parmesano", "2 cucharadas de perejil recién picado", "pimienta negra recién molida"],
 ["Caliente el aceite en una sartén grande antiadherente, agregue la cebolla y el ajo y fría durante 1 minuto. Agregue el pollo y siga friendo de 2 a 3 minutos.", "Incorpore el arroz y mezcle para que se cubra con el aceite. Agregue poco a poco el caldo caliente, revolviendo continuamente y dejando que se absorba cada porción antes de agregar la siguiente.", "Incorpore los espárragos y los chícharos con la última porción de caldo y continúe la cocción. Todo el proceso de cocción debe tomar unos 20 minutos y el arroz debe quedar «al dente».", "Mezcle con el queso parmesano y el perejil, sazone bien y sirva."],
 ["Mantenga el caldo caliente en otra olla para que, al agregarlo al plato, no baje la temperatura y detenga la cocción del arroz.", "Para una alternativa vegetariana, omita el queso parmesano, agregue 200 g de champiñones en lugar de pollo y use caldo de verduras.", "Instrucciones para congelar: Se puede congelar una vez cocido. Descongele en el refrigerador y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por ración: 1"]),
("ريزوتو الدجاج مع خضار الربيع", "عشاء يومي مليء بالعناصر الغذائية.", "4", "293 غرام",
 ["1 ملعقة صغيرة زيت زيتون", "1 بصلة صغيرة، مفرومة ناعمًا", "1 فص ثوم، مهروس", "2 صدر دجاج بدون عظم وبدون جلد، مقطع مكعبات", "225 غرام أرز ريزوتو", "1 لتر مرق دجاج ساخن", "1 عبوة 100 غرام هليون، مقطوعة إلى نصفين", "150 غرام بازلاء مجمدة", "2 ملعقة كبيرة جبن بارميزان", "2 ملعقة كبيرة بقدونس مفروم طازجًا", "فلفل أسود مطحون طازجًا"],
 ["سخّن الزيت في مقلاة كبيرة غير لاصقة، وأضف البصل والثوم وقلّبهما لمدة 1 دقيقة. أضف الدجاج واستمر في التقليب لمدة 2-3 دقائق.", "أضف الأرز وحرّكه ليتغطى بالزيت. أضف المرق الساخن تدريجيًا مع التحريك المستمر، واترك كل إضافة تُمتص قبل إضافة التالية.", "أضف الهليون والبازلاء مع آخر كمية من المرق واستمر في الطهي. يجب أن تستغرق عملية الطهي كلها حوالي 20 دقيقة ويجب أن يكون الأرز «ألدنتي» (متماسكًا قليلًا).", "حرّك الجبن البارميزان والبقدونس في الطبق، وتبّل جيدًا وقدّم."],
 ["أبقِ المرق ساخنًا في قدر آخر حتى لا يخفض درجة حرارة الطبق عند إضافته فيوقف نضج الأرز.", "للحصول على بديل نباتي، احذف جبن البارميزان وأضف 200 غرام فطر بدلًا من الدجاج واستخدم مرق الخضار.", "تعليمات التجميد: يمكن تجميده بعد الطهي. ذوّبه في الثلاجة وأعد تسخينه حتى يصبح ساخنًا جدًا في كل جزء منه.", "حصص الفاكهة/الخضار لكل حصة: 1"])))
build(4, R)
